const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const now = new Date();
const todayStr = now.toISOString().slice(0,10);

rows.sort((a,b) => new Date(a.appointmentDateTime) - new Date(b.appointmentDateTime));

const today = rows.filter(r => r.status !== 'cancelled' && (r.appointmentDateTime||'').startsWith(todayStr));
const upcoming = rows.filter(r => r.status !== 'cancelled' && r.appointmentDateTime > todayStr + 'T23:59:59' );
const cancelled = rows.filter(r => r.status === 'cancelled');
const past = rows.filter(r => r.status !== 'cancelled' && r.appointmentDateTime < todayStr);

function fmt(dt) {
  if (!dt) return '-';
  const d = new Date(dt);
  return d.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' }) + ' at ' + d.toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit' });
}

function row(r, statusClass) {
  return `<tr>
    <td>#${r.id}</td>
    <td><strong>${r.patientName || '-'}</strong></td>
    <td>${r.phone || '-'}</td>
    <td>${r.email || '-'}</td>
    <td>${r.service || '-'}</td>
    <td>${fmt(r.appointmentDateTime)}</td>
    <td><span class="badge ${statusClass}">${r.status || 'confirmed'}</span></td>
  </tr>`;
}

function table(list, statusClass, emptyMsg) {
  if (!list.length) return `<p class="empty">${emptyMsg}</p>`;
  return `<table><thead><tr><th>ID</th><th>Patient</th><th>Phone</th><th>Email</th><th>Service</th><th>Date & Time</th><th>Status</th></tr></thead><tbody>${list.map(r => row(r, statusClass)).join('')}</tbody></table>`;
}

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bright Smile Dental — Dashboard</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: -apple-system, Arial, sans-serif; background: #f4f8fb; color: #16324f; margin: 0; padding: 24px; }
  .header { max-width: 1100px; margin: 0 auto 24px; }
  .header h1 { font-size: 24px; margin: 0 0 4px; }
  .header p { color: #6b8299; margin: 0; font-size: 14px; }
  .stats { display: flex; gap: 16px; max-width: 1100px; margin: 0 auto 28px; flex-wrap: wrap; }
  .stat-card { background: #fff; border-radius: 12px; padding: 16px 20px; box-shadow: 0 4px 14px rgba(22,50,79,.06); min-width: 130px; flex: 1; }
  .stat-card .num { font-size: 26px; font-weight: 700; color: #137c8b; }
  .stat-card .label { font-size: 13px; color: #6b8299; margin-top: 2px; }
  .section { max-width: 1100px; margin: 0 auto 32px; background: #fff; border-radius: 14px; padding: 20px 22px; box-shadow: 0 4px 14px rgba(22,50,79,.06); }
  .section h2 { font-size: 17px; margin: 0 0 14px; display: flex; align-items: center; gap: 8px; }
  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  th { text-align: left; color: #6b8299; font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: .04em; padding: 8px 10px; border-bottom: 2px solid #eef3f7; }
  td { padding: 10px; border-bottom: 1px solid #eef3f7; }
  tr:hover td { background: #f9fbfd; }
  .badge { padding: 4px 10px; border-radius: 20px; font-size: 12px; font-weight: 600; }
  .badge.confirmed { background: #e6f7f2; color: #0f9d6a; }
  .badge.cancelled { background: #fdeceb; color: #d9483b; }
  .empty { color: #93a5b5; font-size: 14px; padding: 6px 0; }
  .refresh { display: inline-block; margin-top: 6px; font-size: 13px; color: #137c8b; text-decoration: none; }
</style></head>
<body>
  <div class="header">
    <h1>🦷 Bright Smile Dental — Appointments</h1>
    <p>Live view of all patient bookings. <a class="refresh" href="">Refresh</a></p>
  </div>
  <div class="stats">
    <div class="stat-card"><div class="num">${today.length}</div><div class="label">Today</div></div>
    <div class="stat-card"><div class="num">${upcoming.length}</div><div class="label">Upcoming</div></div>
    <div class="stat-card"><div class="num">${cancelled.length}</div><div class="label">Cancelled</div></div>
    <div class="stat-card"><div class="num">${rows.length}</div><div class="label">Total Bookings</div></div>
  </div>
  <div class="section"><h2>📅 Today</h2>${table(today, 'confirmed', 'No appointments today.')}</div>
  <div class="section"><h2>⏭️ Upcoming</h2>${table(upcoming, 'confirmed', 'No upcoming appointments.')}</div>
  <div class="section"><h2>❌ Cancelled</h2>${table(cancelled, 'cancelled', 'No cancelled appointments.')}</div>
</body></html>`;

return [{ json: { html } }];
